\begin{proposition}
Let $G$ be a totally disconnected locally compact group, $\phi:G\to G$ a topological automorphism and $k$ a positive integer. Then $h_{top}(\phi^k)=k\cdot h_{top}(\phi)$.
\end{proposition}
\begin{proof}
Let $U\in\mathcal B(G)$ and denote $C=C(\phi^{-1},U)$. We start noting that $$C=C(\phi^{-k},V),\ \text{where}\ V=C_k(\phi^{-1},U).$$
 Moreover, $\phi^{n+1}(C)\supseteq \phi^n(C)$ and $[\phi^{n+1}(C):\phi^n(C)]=[\phi(C):C]$ for every $n\geq0$, applying the automorphism $\phi^{-n}$. Then Fact \ref{gi}(a) gives 
\begin{align*}
[\phi^k(C):C]&=[\phi^k(C):\phi^{k-1}(C)]\cdot[\phi^{k-1}(C):\phi^{k-2}(C)]\cdot\ldots\cdot[\phi(C):C]\\
&=[\phi(C):C]^k.
\end{align*}
Therefore, $$[\phi^k(C(\phi^{-k},V)):C(\phi^{-k},V)]=[\phi^k(C):C]=[\phi(C):C]^k;$$
so Theorem \ref{lf+} implies $$H_{top}(\phi^k,V)=k\cdot H_{top}(\phi,U).$$
This immediately gives $h_{top}(\phi^k)\geq k\cdot h_{top}(\phi)$.
By Lemma \ref{antim}, since $V\subseteq U$, we have also $$H_{top}(\phi^k,U)\leq H_{top}(\phi^k,V)=k \cdot H_{top}(\phi,U),$$
so the missing converse inequality $h_{top}(\phi^k)\leq k\cdot h_{top}(\phi)$ holds as well, and this concludes the proof.

\begin{theorem}
Let $G$ and $H$ be totally disconnected locally compact groups, $\phi:G\to G$ and $\psi:H\to H$ topological automorphisms. Then $h_{top}(\phi\times \psi)=h_{top}(\phi)+h_{top}(\psi)$.
\end{theorem}
\begin{proof}
Let $\eta=\phi\times\psi$. Since the family $\mathcal B=\mathcal B(G)\times\mathcal B(H)$ is a local base at $1$ of $G\times H$, in view of Corollary \ref{basesuff} it suffices to take $U\in\mathcal B(G)$ and $V\in\mathcal B(H)$, and to verify that $$H_{top}(\eta,U\times V)=H_{top}(\phi,U)+H_{top}(\psi,V);$$
this holds since $C(\eta^{-1},U\times V)=C(\phi^{-1},U)\times C(\psi^{-1},V)$, so
$$[\eta(C(\eta^{-1},U\times V)):C(\eta^{-1},U\times V)]=[\phi(C(\phi^{-1},U)):C(\phi^{-1},U)]\cdot[\psi(C(\psi^{-1},V)):C(\psi^{-1},V)],$$
and Theorem \ref{lf+} concludes the proof.

\begin{proof}
